 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Fix isolated single-cell speckles by their four-neighbor majority.
    seen = set()
    for r in range(h):
        for c in range(w):
            if (r,c) in seen:
                continue
            color=grid[r][c]
            comp=[(r,c)]; seen.add((r,c))
            for y,x in comp:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); comp.append((yy,xx))
            if len(comp)==1:
                y,x=comp[0]
                neighbors=[grid[yy][xx] for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)) if 0<=yy<h and 0<=xx<w]
                if neighbors:
                    counts=Counter(neighbors)
                    best=max(counts.values())
                    choices=[v for v,n in counts.items() if n==best]
                    if len(choices)==1:
                        out[y][x]=choices[0]
                    else:
                        # On a tie, extend the color whose run continues farthest through this row/column.
                        def reach(v):
                            score=0
                            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                                yy,xx=y+dy,x+dx
                                while 0<=yy<h and 0<=xx<w and grid[yy][xx]==v:
                                    score+=1; yy+=dy; xx+=dx
                            return score
                        out[y][x]=max(choices,key=reach)
    return out
