                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); comp.append((yy,xx))
            if len(comp)>1 and color != background:
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                box=(min(rs),max(rs),min(cs),max(cs))
                area=(box[1]-box[0]+1)*(box[3]-box[2]+1)
                components.append((color,box,len(comp)/area))
    out=[row[:] for row in grid]
    seen.clear()
    for r in range(h):
        for c in range(w):
            if (r,c) in seen: continue
