                    candidates.append((density,col))
            if candidates:
                out[y][x]=max(candidates)[1]
                continue
            # Fill a one-cell gap between same-colored regions on a straight line.
            bridge=None
            for dy,dx in ((1,0),(0,1)):
                y0,x0=y-dy,x-dx; y1,x1=y+dy,x+dx
                if 0<=y0<h and 0<=x0<w and 0<=y1<h and 0<=x1<w:
