            for y,x in q:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color,q))
    comp_sizes={}
    for color,q in comps:
        comp_sizes.setdefault(color,[]).append(len(q))
    seen.clear()
    for r in range(h):
      for c in range(w):
        if (r,c) in seen: continue
        color=grid[r][c]; q=[(r,c)]; seen.add((r,c))
        for y,x in q:
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx));q.append((yy,xx))
        if len(q)!=1: continue
        y,x=q[0]
        # Strongest local evidence from full 8-neighborhood, then 4-neighbors.
        around=[grid[yy][xx] for yy in range(max(0,y-1),min(h,y+2)) for xx in range(max(0,x-1),min(w,x+2)) if (yy,xx)!=(y,x)]
        counts=Counter(around)
        if not counts: continue
        m=max(counts.values()); choices=[v for v,n in counts.items() if n==m]
        if len(choices)>1:
