def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    dense_boxes = []
    components = []
    for r in range(h):
        for c in range(w):
            if (r,c) in seen:
                continue
            color = grid[r][c]
            q = [(r,c)]
            seen.add((r,c))
            for y,x in q:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx = y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            components.append((color,q))
            if color != background and len(q) >= 4:
                rs=[y for y,x in q]; cs=[x for y,x in q]
                box=(min(rs),max(rs),min(cs),max(cs))
                area=(box[1]-box[0]+1)*(box[3]-box[2]+1)
                density=len(q)/area
                if density >= 0.75:
                    dense_boxes.append((color,box,density,len(q)))
    out=[row[:] for row in grid]
    for color,q in components:
        if len(q)!=1:
            continue
        y,x=q[0]
        enclosing=[item for item in dense_boxes if item[1][0]<=y<=item[1][1] and item[1][2]<=x<=item[1][3]]
        if enclosing:
            enclosing.sort(key=lambda item:(item[2],item[3]),reverse=True)
            out[y][x]=enclosing[0][0]
        else:
            out[y][x]=background
    return out
