        if len(comp) != 1:
            continue
        r, c = comp[0]
        possible = [b for b in boxes if b[1] <= r <= b[2] and b[3] <= c <= b[4]]
        if possible:
            possible.sort(key=lambda b: (b[5], b[6]), reverse=True)
            out[r][c] = possible[0][0]
